  `funding_available_balance` decimal(28,8) NOT NULL DEFAULT '0.00000000' COMMENT '最多能放贷的金额',
  `total_funding_position_balance` decimal(28,8) NOT NULL DEFAULT '0.00000000' COMMENT '持仓中的金额',
